// NewTransport builds an *http.Transport with the configured dial timeout
// and a baseline TLS config. Callers wrap the returned transport with their
// own RoundTripper as needed (e.g. debug logging) and assemble their own
// *http.Client around it.
//
// ForceAttemptHTTP2 is set because net/http's auto-HTTP/2 path bails out
// conservatively whenever a custom DialContext or TLSClientConfig is present
// (see (*http.Transport).protocols in Go's stdlib) — and we set both. Without
// this flag the transport advertises only http/1.1 in ALPN and every caller
// (the data-plane Proxy in internal/remotehelper/transport, the bootstrap
// client in git-remote-entire, the cluster well-known probe, the login-JWT
// refresh provider, and the repo-scoped token exchange) is pinned to
// HTTP/1.1. http.DefaultTransport itself sets ForceAttemptHTTP2 for the same
// reason; we mirror that here.
func NewTransport(skipTLSVerify bool) *http.Transport {
	return &http.Transport{
		ForceAttemptHTTP2: true,
		DialContext:       (&net.Dialer{Timeout: DialTimeout()}).DialContext,
		TLSClientConfig: &tls.Config{
			MinVersion:         tls.VersionTLS12,
			InsecureSkipVerify: skipTLSVerify, //nolint:gosec // intentional for local development
		},
	}
}

