// TestNewTransport_NegotiatesHTTP2 pins the ForceAttemptHTTP2 wiring by
// driving a real ALPN handshake against an httptest TLS server. Without
// ForceAttemptHTTP2 the transport's custom DialContext + TLSClientConfig
// trip Go's conservative auto-disable and the handshake settles on
// HTTP/1.1, locking every caller (data-plane mirror traffic, repo-scoped
// token exchange, login refresh) to HTTP/1.1.
func TestNewTransport_NegotiatesHTTP2(t *testing.T) {
	t.Parallel()

	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusNoContent)
	}))
	srv.EnableHTTP2 = true
	srv.StartTLS()
	t.Cleanup(srv.Close)

	transport := NewTransport(true) // skip TLS verify; the httptest cert is self-signed
	client := &http.Client{Transport: transport}
	t.Cleanup(transport.CloseIdleConnections)

	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, srv.URL, nil)
	if err != nil {
		t.Fatalf("new request: %v", err)
	}
	resp, err := client.Do(req)
	if err != nil {
		t.Fatalf("client.Do: %v", err)
	}
	t.Cleanup(func() { _ = resp.Body.Close() })

	if resp.ProtoMajor != 2 {
		t.Fatalf("negotiated %s, want HTTP/2.0 — ForceAttemptHTTP2 likely got dropped from NewTransport", resp.Proto)
	}
}

